1	package review
2	
3	import (
4		"context"
5		"errors"
6		"fmt"
7		"sort"
8		"strings"
9	
10		"github.com/entireio/cli/cmd/entire/cli/agent"
11		"github.com/entireio/cli/cmd/entire/cli/agent/types"
12		reviewtypes "github.com/entireio/cli/cmd/entire/cli/review/types"
13		"github.com/entireio/cli/cmd/entire/cli/settings"
14	)
15	
16	const DefaultProfileName = "general"
17	
18	const (
19		defaultGeneralTask       = "Review this change for correctness, regressions, API design, missing tests, maintainability, and user-facing behavior changes. Report only actionable findings with concrete evidence."
20		defaultSecurityTask      = "Review this change for security vulnerabilities: authentication and authorization bugs, injection risks, secrets exposure, unsafe dependency or deserialization behavior, privilege-boundary mistakes, insecure defaults, and data leakage. Report only actionable findings with concrete evidence."
21		defaultAccessibilityTask = "Review this change for accessibility regressions: keyboard navigation, focus management, semantic markup, labels, ARIA correctness, color contrast, reduced-motion behavior, screen-reader behavior, and inclusive error states. Report only actionable findings with concrete evidence."
22	)
23	
24	// profileTask returns the configured task, or a built-in task for conventional
25	// profile names when the config leaves task empty.
26	func profileTask(name string, cfg settings.ReviewProfileConfig) string {
27		if strings.TrimSpace(cfg.Task) != "" {
28			return strings.TrimSpace(cfg.Task)
29		}
30		switch strings.ToLower(name) {
31		case "", DefaultProfileName:
32			return defaultGeneralTask
33		case "security":
34			return defaultSecurityTask
35		case "accessibility", "a11y":
36			return defaultAccessibilityTask
37		default:
38			return defaultGeneralTask
39		}
40	}
41	
42	// selectReviewProfile resolves the profile to run. No legacy fallback is used:
43	// users must configure review_profiles (the command is experimental, so there
44	// is intentionally no migration from the old review map).
45	func selectReviewProfile(s *settings.EntireSettings, override string) (string, settings.ReviewProfileConfig, error) {
46		if s == nil || len(s.ReviewProfiles) == 0 {
47			return "", settings.ReviewProfileConfig{}, errors.New("no crew profiles configured; run `entire scout --configure` or add review_profiles to Entire preferences")
48		}
49		profiles := nonZeroProfiles(s.ReviewProfiles)
50		if len(profiles) == 0 {
51			return "", settings.ReviewProfileConfig{}, errors.New("no review profiles configured; every profile is empty")
52		}
53	
54		name := strings.TrimSpace(override)
55		if name == "" {
56			name = strings.TrimSpace(s.ReviewDefaultProfile)
57		}
58		if name == "" {
59			if _, ok := profiles[DefaultProfileName]; ok {
60				name = DefaultProfileName
61			} else if len(profiles) == 1 {
62				for only := range profiles {
63					name = only
64				}
65			} else {
66				return "", settings.ReviewProfileConfig{}, fmt.Errorf(
67					"multiple review profiles configured (%s); pass a profile name or set review_default_profile",
68					strings.Join(sortedProfileNames(profiles), ", "))
69			}
70		}
71	
72		cfg, ok := profiles[name]
73		if !ok {
74			return "", settings.ReviewProfileConfig{}, fmt.Errorf(
75				"review profile %q is not configured; configured profiles: %s",
76				name, strings.Join(sortedProfileNames(profiles), ", "))
77		}
78		if len(nonZeroAgentConfigs(cfg.Agents)) == 0 {
79			return "", settings.ReviewProfileConfig{}, fmt.Errorf("review profile %q has no configured agents", name)
80		}
81		return name, cfg, nil
82	}
83	
84	func nonZeroProfiles(in map[string]settings.ReviewProfileConfig) map[string]settings.ReviewProfileConfig {
85		out := make(map[string]settings.ReviewProfileConfig, len(in))
86		for name, cfg := range in {
87			name = strings.TrimSpace(name)
88			if name == "" || cfg.IsZero() {
89				continue
90			}
91			out[name] = cfg
92		}
93		return out
94	}
95	
96	func sortedProfileNames(in map[string]settings.ReviewProfileConfig) []string {
97		names := make([]string, 0, len(in))
98		for name := range in {
99			names = append(names, name)
100		}
101		sort.Strings(names)
102		return names
103	}
104	
105	func nonZeroAgentConfigs(in map[string]settings.ReviewConfig) map[string]settings.ReviewConfig {
106		out := make(map[string]settings.ReviewConfig, len(in))
107		for name, cfg := range in {
108			name = strings.TrimSpace(name)
109			if name == "" || cfg.IsZero() {
110				continue
111			}
112			out[name] = cfg
113		}
114		return out
115	}
116	
117	func sortedProfileAgentNames(profile settings.ReviewProfileConfig) []string {
118		names := make([]string, 0, len(profile.Agents))
119		for name := range profile.Agents {
120			names = append(names, name)
121		}
122		sort.Strings(names)
123		return names
124	}
125	
126	func reviewAgentName(workerName string, cfg settings.ReviewConfig) string {
127		if strings.TrimSpace(cfg.Agent) != "" {
128			return strings.TrimSpace(cfg.Agent)
129		}
130		return strings.TrimSpace(workerName)
131	}
132	
133	func reviewWorkerLabel(workerName string, cfg settings.ReviewConfig) string {
134		agentName := reviewAgentName(workerName, cfg)
135		parts := []string{workerName}
136		var details []string
137		if agentName != "" && agentName != workerName {
138			details = append(details, agentName)
139		}
140		if strings.TrimSpace(cfg.Model) != "" {
141			details = append(details, "model "+strings.TrimSpace(cfg.Model))
142		}
143		if len(details) > 0 {
144			parts = append(parts, "  ("+strings.Join(details, ", ")+")")
145		}
146		return strings.Join(parts, "")
147	}
148	
149	// profileMasterIdentity resolves the master's agent name and model, and reports
150	// whether the profile has a master at all. A standalone master (MasterAgent
151	// set) wins and need not be one of the workers; otherwise the legacy worker
152	// master (Master keying into Agents) is resolved.
153	func profileMasterIdentity(profile settings.ReviewProfileConfig) (string, string, bool) {
154		if ma := strings.TrimSpace(profile.MasterAgent); ma != "" {
155			return ma, strings.TrimSpace(profile.MasterModel), true
156		}
157		workerName, cfg, err := selectProfileWorker(profile, profile.Master)
158		if err != nil {
159			return "", "", false
160		}
161		model := strings.TrimSpace(profile.MasterModel)
162		if model == "" {
163			model = strings.TrimSpace(cfg.Model)
164		}
165		return reviewAgentName(workerName, cfg), model, true
166	}
167	
168	func resolveProfileMaster(profile settings.ReviewProfileConfig) (string, string) {
169		agentName, model, _ := profileMasterIdentity(profile)
170		return agentName, model
171	}
172	
173	// masterDisplayLabel renders the master for UI/dump output: "agent · model" for
174	// a standalone master, or the worker label for a legacy worker master.
175	func masterDisplayLabel(profile settings.ReviewProfileConfig, agentName, model string) string {
176		if strings.TrimSpace(profile.MasterAgent) != "" {
177			if strings.TrimSpace(model) != "" {
178				return labelForSimpleAgent(agentName) + " · " + model
179			}
180			return labelForSimpleAgent(agentName)
181		}
182		if workerName, cfg, err := selectProfileWorker(profile, profile.Master); err == nil {
183			return reviewWorkerLabel(workerName, cfg)
184		}
185		return agentName
186	}
187	
188	func selectProfileWorker(profile settings.ReviewProfileConfig, selector string) (string, settings.ReviewConfig, error) {
189		selector = strings.TrimSpace(selector)
190		if selector == "" {
191			return "", settings.ReviewConfig{}, errors.New("empty review worker selector")
192		}
193		if cfg, ok := profile.Agents[selector]; ok && !cfg.IsZero() {
194			return selector, cfg, nil
195		}
196		var matches []string
197		for workerName, cfg := range profile.Agents {
198			if cfg.IsZero() {
199				continue
200			}
201			if reviewAgentName(workerName, cfg) == selector {
202				matches = append(matches, workerName)
203			}
204		}
205		sort.Strings(matches)
206		switch len(matches) {
207		case 1:
208			return matches[0], profile.Agents[matches[0]], nil
209		case 0:
210			configured := sortedProfileAgentNames(profile)
211			if len(configured) == 0 {
212				return "", settings.ReviewConfig{}, fmt.Errorf("review worker or agent %q is not configured", selector)
213			}
214			return "", settings.ReviewConfig{}, fmt.Errorf("review worker or agent %q is not configured; configured workers: %s", selector, strings.Join(configured, ", "))
215		default:
216			return "", settings.ReviewConfig{}, fmt.Errorf("agent %q has multiple review workers (%s); choose one by worker name", selector, strings.Join(matches, ", "))
217		}
218	}
219	
220	func workerIDForAgentModel(agentName, model string, existing map[string]settings.ReviewConfig) string {
221		base := strings.TrimSpace(agentName)
222		if strings.TrimSpace(model) != "" {
223			base += ":" + sanitizeWorkerIDPart(model)
224		}
225		if base == "" {
226			base = "worker"
227		}
228		candidate := base
229		for i := 2; ; i++ {
230			if _, exists := existing[candidate]; !exists {
231				return candidate
232			}
233			candidate = fmt.Sprintf("%s-%d", base, i)
234		}
235	}
236	
237	func sanitizeWorkerIDPart(s string) string {
238		s = strings.ToLower(strings.TrimSpace(s))
239		var b strings.Builder
240		lastDash := false
241		for _, r := range s {
242			keep := (r >= 'a' && r <= 'z') || (r >= '0' && r <= '9')
243			if keep {
244				b.WriteRune(r)
245				lastDash = false
246				continue
247			}
248			if !lastDash {
249				b.WriteByte('-')
250				lastDash = true
251			}
252		}
253		out := strings.Trim(b.String(), "-")
254		if out == "" {
255			return "model"
256		}
257		return out
258	}
259	
260	func defaultReviewProfileForInstalledAgents(
261		ctx context.Context,
262		profileName string,
263		installed []types.AgentName,
264		reviewerFor func(string) reviewtypes.AgentReviewer,
265	) (settings.ReviewProfileConfig, error) {
266		profileName = strings.TrimSpace(profileName)
267		if profileName == "" {
268			profileName = DefaultProfileName
269		}
270		installedNames := make([]string, 0, len(installed))
271		for _, name := range installed {
272			installedNames = append(installedNames, string(name))
273		}
274		sort.Strings(installedNames)
275	
276		agents := make(map[string]settings.ReviewConfig, len(installedNames))
277		for _, name := range installedNames {
278			if reviewerFor != nil && reviewerFor(name) == nil {
279				continue
280			}
281			cfg := defaultReviewAgentConfig(profileName, name)
282			if cfg.IsZero() {
283				continue
284			}
285			agents[name] = cfg
286		}
287		if len(agents) == 0 {
288			return settings.ReviewProfileConfig{}, errors.New("no agents with review runner adapters and hooks installed; run `entire configure --agent claude-code`, `entire configure --agent codex`, or `entire configure --agent gemini`")
289		}
290		return settings.ReviewProfileConfig{
291			Task:   profileTask(profileName, settings.ReviewProfileConfig{}),
292			Agents: agents,
293			Master: defaultReviewMaster(ctx, agents),
294		}, nil
295	}
296	
297	func defaultReviewAgentConfig(profileName, agentName string) settings.ReviewConfig {
298		focus := defaultProfileFocus(profileName)
299		switch agentName {
300		case string(agent.AgentNameClaudeCode):
301			if strings.EqualFold(profileName, "security") {
302				return settings.ReviewConfig{Skills: []string{"/security-review"}}
303			}
304			return settings.ReviewConfig{Skills: []string{"/review"}, Prompt: focus}
305		case string(agent.AgentNameCodex):
306			return settings.ReviewConfig{Skills: []string{"/review"}, Prompt: focus}
307		case string(agent.AgentNameGemini):
308			prompt := "Review the change according to the profile task."
309			if focus != "" {
310				prompt += " " + focus
311			}
312			return settings.ReviewConfig{Prompt: prompt}
313		default:
314			return settings.ReviewConfig{}
315		}
316	}
317	
318	func defaultProfileFocus(profileName string) string {
319		switch strings.ToLower(strings.TrimSpace(profileName)) {
320		case "security":
321			return "Focus specifically on security issues."
322		case "accessibility", "a11y":
323			return "Focus specifically on accessibility issues."
324		default:
325			return ""
326		}
327	}
328	
329	func defaultReviewMaster(ctx context.Context, configured map[string]settings.ReviewConfig) string {
330		for _, preferred := range []string{string(agent.AgentNameClaudeCode), string(agent.AgentNameCodex), string(agent.AgentNameGemini)} {
331			for _, workerName := range sortedReviewConfigKeys(configured) {
332				cfg := configured[workerName]
333				if reviewAgentName(workerName, cfg) == preferred && agentSupportsTextGeneration(ctx, preferred) {
334					return workerName
335				}
336			}
337		}
338		for _, workerName := range sortedReviewConfigKeys(configured) {
339			if agentSupportsTextGeneration(ctx, reviewAgentName(workerName, configured[workerName])) {
340				return workerName
341			}
342		}
343		return ""
344	}
345	
346	func sortedReviewConfigKeys(configured map[string]settings.ReviewConfig) []string {
347		names := make([]string, 0, len(configured))
348		for name := range configured {
349			names = append(names, name)
350		}
351		sort.Strings(names)
352		return names
353	}
354	
355	func agentSupportsTextGeneration(_ context.Context, name string) bool {
356		ag, err := agent.Get(types.AgentName(name))
357		if err != nil {
358			return false
359		}
360		_, ok := agent.AsTextGenerator(ag)
361		return ok
362	}
363	
364	func saveDefaultReviewProfile(ctx context.Context, profileName string, profile settings.ReviewProfileConfig) error {
365		return saveReviewProfile(ctx, profileName, profile, false)
366	}
367	
368	func saveReviewProfile(ctx context.Context, profileName string, profile settings.ReviewProfileConfig, makeDefault bool) error {
369		prefs, err := settings.LoadClonePreferences(ctx)
370		if err != nil {
371			return fmt.Errorf("load review preferences before save: %w", err)
372		}
373		if prefs == nil {
374			prefs = &settings.ClonePreferences{}
375		}
376		if prefs.ReviewProfiles == nil {
377			prefs.ReviewProfiles = map[string]settings.ReviewProfileConfig{}
378		}
379		prefs.ReviewProfiles[profileName] = profile
380		if makeDefault || prefs.ReviewDefaultProfile == "" {
381			prefs.ReviewDefaultProfile = profileName
382		}
383		if err := settings.SaveClonePreferences(ctx, prefs); err != nil {
384			return fmt.Errorf("save review preferences: %w", err)
385		}
386		return nil
387	}
