44	// ConfirmFirstRunSetup prints a banner framing the picker as first-run
45	// setup (rather than the review itself) and waits for the user to confirm.
46	// Returns false if the user cancels; caller should bail gracefully.
47	//
48	// Signposting matters here because `entire review` with no config silently
49	// drops into the picker — users running the command to start a review can
50	// mistake the picker for the review. The banner + confirmation makes the
51	// setup phase explicit, and the trailing "running review now" line in the
52	// caller closes the loop on what comes next.
53	func ConfirmFirstRunSetup(ctx context.Context, out io.Writer) bool {
54		fmt.Fprintln(out, "No review profiles found — let's set one up first.")
55		fmt.Fprintln(out)
56		fmt.Fprintln(out, "You'll choose a review type and worker agents. They're saved to")
57		fmt.Fprintln(out, "local review preferences; configure later with `entire scout --configure`.")
58		fmt.Fprintln(out, "After setup, you can start the review immediately.")
59		fmt.Fprintln(out)
60	
61		proceed := true
62		form := newAccessibleForm(huh.NewGroup(
63			huh.NewConfirm().
64				Title("Set up review now?").
65				Affirmative("Yes").
66				Negative("Cancel").
67				Value(&proceed),
68		))
69		if err := form.RunWithContext(ctx); err != nil {
70			fmt.Fprintln(out, "Setup cancelled.")
71			return false
72		}
73		if !proceed {
74			fmt.Fprintln(out, "Setup cancelled.")
75		}
76		return proceed
77	}
