79	// RunReviewGuidedSetup is the simple config path for `entire review`.
80	// It intentionally avoids the per-agent skills picker: users choose the review
81	// profile and worker agents, then Entire fills in opinionated per-agent
82	// defaults. Advanced skill-level editing remains available via --edit.
83	func RunReviewGuidedSetup(
84		ctx context.Context,
85		out io.Writer,
86		installed []types.AgentName,
87		reviewerFor func(string) reviewtypes.AgentReviewer,
88		profileName string,
89		firstRun bool,
90	) (string, settings.ReviewProfileConfig, error) {
91		if firstRun {
92			if !ConfirmFirstRunSetup(ctx, out) {
93				return "", settings.ReviewProfileConfig{}, ErrPickerCancelled
94			}
95		}
96	
97		launchable := launchableInstalledAgentNames(installed, reviewerFor)
98		if len(launchable) == 0 {
99			return "", settings.ReviewProfileConfig{}, errors.New("no agents with review runner adapters and hooks installed; run `entire configure --agent claude-code`, `entire configure --agent codex`, or `entire configure --agent gemini`")
100		}
101	
102		profileName = strings.TrimSpace(profileName)
103		profileWasProvided := profileName != ""
104		if profileName == "" {
105			profileName = DefaultProfileName
106		}
107		if !profileWasProvided {
108			pickedProfile, err := promptForSimpleReviewProfile(ctx)
109			if err != nil {
110				return "", settings.ReviewProfileConfig{}, err
111			}
112			profileName = pickedProfile
113		}
114	
115		profile, err := promptForReviewCrew(ctx, profileName, launchable)
116		if err != nil {
117			return "", settings.ReviewProfileConfig{}, err
118		}
119		if len(profile.Agents) > 1 {
120			masterAgent, masterModel, err := promptForStandaloneMaster(ctx, launchable)
121			if err != nil {
122				return "", settings.ReviewProfileConfig{}, err
123			}
124			profile.MasterAgent = masterAgent
125			profile.MasterModel = masterModel
126			profile.Master = ""
127		}
128		fmt.Fprintf(out, "Saved %q review profile with %s.\n", profileName, strings.Join(sortedProfileAgentNames(profile), ", "))
129		fmt.Fprintln(out)
130		return profileName, profile, nil
131	}
