133	// RunReviewConfigPicker presents a huh multi-select for each installed agent
134	// that has curated review skills, and saves the selection to
135	// clone-local review preferences. Previously-saved skills are pre-checked via
136	// huh.Option.Selected(true), mirroring how `entire enable` preserves prior
137	// selections in its own agent picker.
138	//
139	// getInstalled is injected to avoid an import cycle with the cli package.
140	func launchableInstalledAgentNames(installed []types.AgentName, reviewerFor func(string) reviewtypes.AgentReviewer) []string {
141		names := make([]string, 0, len(installed))
142		for _, name := range installed {
143			if reviewerFor != nil && reviewerFor(string(name)) == nil {
144				continue
145			}
146			names = append(names, string(name))
147		}
148		sort.Strings(names)
149		return names
150	}
