170	// crewSlot is one worker slot in the review crew: an agent plus an optional
171	// model ("" means the agent's own default). Duplicate slots — the same agent
172	// and model — are allowed; each becomes its own worker.
173	type crewSlot struct {
174		agent string
175		model string
176	}
177	
178	// promptForReviewCrew builds the review crew on a single screen. It seeds one
179	// slot per launchable agent (the guided default is "all agents"), then lets the
180	// user add, edit, or remove slots from a list until Done. Duplicate slots (same
181	// agent and model) are allowed; each becomes its own worker.
182	func promptForReviewCrew(ctx context.Context, profileName string, launchable []string) (settings.ReviewProfileConfig, error) {
183		slots := make([]crewSlot, 0, len(launchable))
184		for _, name := range launchable {
185			slots = append(slots, crewSlot{agent: name})
186		}
187	
188		const (
189			actAdd     = "add"
190			actDone    = "done"
191			slotPrefix = "slot:"
192		)
193		for {
194			options := make([]huh.Option[string], 0, len(slots)+2)
195			for i, s := range slots {
196				options = append(options, huh.NewOption(fmt.Sprintf("%d  %s", i+1, slotLabel(s)), slotPrefix+strconv.Itoa(i)))
197			}
198			options = append(options, huh.NewOption("+ Add slot", actAdd))
199			if len(slots) > 0 {
200				options = append(options, huh.NewOption(fmt.Sprintf("Done · %d slot(s)", len(slots)), actDone))
201			}
202			picked := actDone
203			if len(slots) == 0 {
204				picked = actAdd
205			}
206			form := newAccessibleForm(huh.NewGroup(
207				huh.NewSelect[string]().
208					Title("Review crew").
209					Description("Select a slot to edit or remove it; + Add slot to add one.").
210					Options(options...).
211					Height(reviewPickerHeight(len(options))).
212					Value(&picked),
213			))
214			if err := form.RunWithContext(ctx); err != nil {
215				return settings.ReviewProfileConfig{}, fmt.Errorf("review crew picker: %w", err)
216			}
217	
218			switch {
219			case picked == actAdd:
220				slot, err := promptCrewSlot(ctx, launchable)
221				if err != nil {
222					return settings.ReviewProfileConfig{}, err
223				}
224				slots = append(slots, slot)
225			case picked == actDone:
226				if len(slots) == 0 {
227					continue
228				}
229				return buildCrewProfile(ctx, profileName, slots), nil
230			case strings.HasPrefix(picked, slotPrefix):
231				idx, convErr := strconv.Atoi(strings.TrimPrefix(picked, slotPrefix))
232				if convErr != nil || idx < 0 || idx >= len(slots) {
233					continue
234				}
235				action, err := promptSlotAction(ctx, slots[idx])
236				if err != nil {
237					return settings.ReviewProfileConfig{}, err
238				}
239				switch action {
240				case "edit":
241					slot, err := promptCrewSlot(ctx, launchable)
242					if err != nil {
243						return settings.ReviewProfileConfig{}, err
244					}
245					slots[idx] = slot
246				case "remove":
247					slots = append(slots[:idx], slots[idx+1:]...)
248				}
249			}
250		}
251	}
