253	// promptCrewSlot prompts for one slot: an agent then a model.
254	func promptCrewSlot(ctx context.Context, launchable []string) (crewSlot, error) {
255		agentName, err := promptCrewAgent(ctx, launchable)
256		if err != nil {
257			return crewSlot{}, err
258		}
259		model, err := promptCrewModel(ctx, agentName)
260		if err != nil {
261			return crewSlot{}, err
262		}
263		return crewSlot{agent: agentName, model: model}, nil
264	}
