266	// buildCrewProfile turns an ordered slot list into a profile. Each slot becomes
267	// a worker keyed by workerIDForAgentModel, which disambiguates duplicates
268	// (claude-code, claude-code-2, claude-code:opus, …).
269	func buildCrewProfile(ctx context.Context, profileName string, slots []crewSlot) settings.ReviewProfileConfig {
270		profile := settings.ReviewProfileConfig{
271			Task:   profileTask(profileName, settings.ReviewProfileConfig{}),
272			Agents: make(map[string]settings.ReviewConfig, len(slots)),
273		}
274		for _, s := range slots {
275			cfg := defaultReviewAgentConfig(profileName, s.agent)
276			// Set Agent explicitly so the worker is valid even when the agent has no
277			// default skills/prompt (e.g. Pi): IsZero is false once Agent is set, and
278			// reviewAgentName resolves the real agent for the worker.
279			cfg.Agent = s.agent
280			cfg.Model = s.model
281			profile.Agents[workerIDForAgentModel(s.agent, s.model, profile.Agents)] = cfg
282		}
283		profile.Master = defaultReviewMaster(ctx, profile.Agents)
284		return profile
285	}
