338	// promptCrewModel picks a model for a slot: Default, an advertised model, or a
339	// Custom… free-text value. Returns "" for the agent's own default.
340	func promptCrewModel(ctx context.Context, agentName string) (string, error) {
341		models := listAgentModelOptions(ctx, agentName)
342		options := make([]huh.Option[string], 0, len(models)+2)
343		options = append(options, huh.NewOption("Default (agent's own default model)", reviewModelDefaultSentinel))
344		for _, m := range models {
345			label := m.ID
346			if m.Note != "" {
347				label = m.ID + "  — " + m.Note
348			}
349			options = append(options, huh.NewOption(label, m.ID))
350		}
351		options = append(options, huh.NewOption("Custom… (type any value)", reviewModelCustomSentinel))
352	
353		picked := reviewModelDefaultSentinel
354		form := newAccessibleForm(huh.NewGroup(
355			huh.NewSelect[string]().
356				Title("Model for " + labelForSimpleAgent(agentName)).
357				Description("Pick a model, Default, or Custom… to type any value.").
358				Options(options...).
359				Height(reviewPickerHeight(len(options))).
360				Value(&picked),
361		))
362		if err := form.RunWithContext(ctx); err != nil {
363			return "", fmt.Errorf("review crew model: %w", err)
364		}
365		switch picked {
366		case reviewModelDefaultSentinel:
367			return "", nil
368		case reviewModelCustomSentinel:
369			model := ""
370			customForm := newAccessibleForm(huh.NewGroup(
371				huh.NewInput().
372					Title("Custom model for " + labelForSimpleAgent(agentName)).
373					Description("Any value accepted by the agent CLI; leave blank for the default.").
374					Value(&model),
375			))
376			if err := customForm.RunWithContext(ctx); err != nil {
377				return "", fmt.Errorf("custom model input: %w", err)
378			}
379			return strings.TrimSpace(model), nil
380		default:
381			return picked, nil
382		}
383	}
