393	// reviewModelCustomSentinel is the select value for "type a custom model".
394	// It cannot collide with a real model id (which never contains spaces).
395	const reviewModelCustomSentinel = "__custom__"
396	
397	// reviewModelDefaultSentinel is the crew multiselect value for "use the agent's
398	// own default model". Resolves to an empty Model string; distinct from a real
399	// model id and from reviewModelCustomSentinel.
400	const reviewModelDefaultSentinel = "__default__"
401	
402	func listAgentModelOptions(ctx context.Context, agentName string) []agent.ModelInfo {
403		ag, err := agent.Get(types.AgentName(agentName))
404		if err != nil {
405			return nil
406		}
407		lister, ok := agent.AsModelLister(ag)
408		if !ok {
409			return nil
410		}
411		models, err := lister.ListModels(ctx)
412		if err != nil {
413			return nil
414		}
415		return models
416	}
