427	// promptForStandaloneMaster picks the standalone master (judge) as its own
428	// agent + model, independent of the worker slots. Candidates are launchable
429	// agents that can write text. Returns (agentName, model).
430	func promptForStandaloneMaster(ctx context.Context, launchable []string) (string, string, error) {
431		candidates := make([]string, 0, len(launchable))
432		for _, name := range launchable {
433			if agentSupportsTextGeneration(ctx, name) {
434				candidates = append(candidates, name)
435			}
436		}
437		if len(candidates) == 0 {
438			return "", "", errors.New("no installed agent can write the final report")
439		}
440	
441		agentName := candidates[0]
442		if len(candidates) > 1 {
443			options := make([]huh.Option[string], 0, len(candidates))
444			for _, name := range candidates {
445				options = append(options, huh.NewOption(labelForSimpleAgent(name), name))
446			}
447			form := newAccessibleForm(huh.NewGroup(
448				huh.NewSelect[string]().
449					Title("Choose the review master").
450					Description("Evaluates the workers' reports and writes the final verdict.").
451					Options(options...).
452					Height(reviewPickerHeight(len(options))).
453					Value(&agentName),
454			))
455			if err := form.RunWithContext(ctx); err != nil {
456				return "", "", fmt.Errorf("master agent picker: %w", err)
457			}
458		}
459		model, err := promptCrewModel(ctx, agentName)
460		if err != nil {
461			return "", "", fmt.Errorf("master model picker: %w", err)
462		}
463		return agentName, model, nil
464	}
