466	func ConfirmRunReviewNow(ctx context.Context, out io.Writer) (bool, error) {
467		runNow := true
468		form := newAccessibleForm(huh.NewGroup(
469			huh.NewConfirm().
470				Title("Start review now?").
471				Affirmative("Start review").
472				Negative("Not now").
473				Value(&runNow),
474		))
475		if err := form.RunWithContext(ctx); err != nil {
476			// Aborting the confirm (Ctrl+C / Esc) is a clean "not now", not a
477			// command error. Surface it as picker-cancelled so the caller maps it
478			// to a silent exit via handlePickerError.
479			fmt.Fprintln(out, "Not started. Run `entire scout` when ready.")
480			return false, ErrPickerCancelled
481		}
482		if !runNow {
483			fmt.Fprintln(out, "Not started. Run `entire scout` when ready.")
484		}
485		return runNow, nil
486	}
