488	func RunReviewConfigPicker(ctx context.Context, out io.Writer, getInstalled func(context.Context) []types.AgentName) (map[string]settings.ReviewConfig, error) {
489		return RunReviewProfileConfigPicker(ctx, out, getInstalled, DefaultProfileName)
490	}
491	
492	func RunReviewProfileConfigPicker(ctx context.Context, out io.Writer, getInstalled func(context.Context) []types.AgentName, profileName string) (map[string]settings.ReviewConfig, error) {
493		profileName = strings.TrimSpace(profileName)
494		if profileName == "" {
495			profileName = DefaultProfileName
496		}
497		installed := getInstalled(ctx)
498		if len(installed) == 0 {
499			return nil, errors.New(
500				"no agents with hooks installed; " +
501					"run 'entire configure --agent <name>' to install hooks for one, " +
502					"or 'entire enable' to set up the repo",
503			)
504		}
505	
506		// Narrow to agents that have a curated skills list; others need manual
507		// editing of clone-local preferences under review.<agent-name>.
508		type configurableAgent struct {
509			name types.AgentName
510			ag   agent.Agent
511		}
512		var configurable []configurableAgent
513		for _, name := range installed {
514			if !skilldiscovery.IsEligible(string(name)) {
515				continue
516			}
517			ag, err := agent.Get(name)
518			if err != nil {
519				continue
520			}
521			configurable = append(configurable, configurableAgent{name: name, ag: ag})
522		}
523		if len(configurable) == 0 {
524			prefsPath, pathErr := settings.ClonePreferencesPath(ctx)
525			if pathErr != nil {
526				return nil, errors.New(
527					"no installed agents have curated review skills; " +
528						"install an eligible agent and run `entire scout --edit`, " +
529						"or edit clone-local review preferences under review.<agent-name>",
530				)
531			}
532			return nil, fmt.Errorf(
533				"no installed agents have curated review skills; "+
534					"install an eligible agent and run `entire scout --edit`, "+
535					"or edit clone-local review preferences (%s) under review.<agent-name>",
536				prefsPath,
537			)
538		}
539	
540		// Load existing profile config so we can pre-check saved skills and seed
541		// saved prompts. A load error here means the settings file is malformed;
542		// log at Warn so users debugging "my saved skills aren't pre-checked" can
543		// see why, but keep going with an empty prefill — runReview already
544		// surfaces the same error distinctly when it's the first load.
545		existing := map[string]settings.ReviewConfig{}
546		existingMaster := ""
547		if s, err := settings.Load(ctx); err != nil {
548			logging.Warn(ctx, "settings.Load failed when pre-filling picker", slog.String("error", err.Error()))
549		} else if s != nil {
550			if profile, ok := s.ReviewProfiles[profileName]; ok {
551				existing = profile.Agents
552				existingMaster = profile.Master
553			}
554		}
555	
556		// Up-front header: make the order and count obvious so users can spot
557		// when an agent they expected isn't being offered (e.g., hooks not
558		// installed for it yet).
559		labels := make([]string, 0, len(configurable))
560		for _, c := range configurable {
561			labels = append(labels, string(c.ag.Type()))
562		}
563		fmt.Fprintf(out, "Configuring review for %d agent(s): %s\n", len(configurable), strings.Join(labels, ", "))
564		fmt.Fprintln(out, "(Previously-saved skills are pre-checked. Space to toggle, enter to confirm.)")
565		fmt.Fprintln(out)
566	
567		selected := map[string]settings.ReviewConfig{}
568		for i, c := range configurable {
569			curated := skilldiscovery.CuratedBuiltinsFor(string(c.name))
570	
571			// Discover + dedupe + filter hints.
572			var discovered []agent.DiscoveredSkill
573			if d, ok := c.ag.(agent.SkillDiscoverer); ok {
574				if ds, dErr := d.DiscoverReviewSkills(ctx); dErr == nil {
575					discovered = ds
576				} else {
577					logging.Debug(ctx, "review discovery failed",
578						slog.String("agent", string(c.name)), slog.String("error", dErr.Error()))
579				}
580			}
581			builtinNames := builtinNameSet(curated)
582			discovered = filterOutBuiltinCollisions(discovered, builtinNames)
583	
584			discoveredSet := make(map[string]struct{}, len(discovered))
585			for _, d := range discovered {
586				discoveredSet[d.Name] = struct{}{}
587			}
588			activeHints := skilldiscovery.ActiveInstallHintsFor(string(c.name), discoveredSet)
589	
590			// Pre-populate pick slices from saved config so the picker preselects
591			// them. The header promises "previously-saved skills are pre-checked";
592			// without this split + Option.Selected(true) in BuildReviewPickerFields,
593			// --edit with accept-defaults silently wipes the agent's saved skills.
594			builtinPicks, discoveredPicks := SplitSavedPicks(
595				existing[string(c.name)].Skills, curated, discovered,
596			)
597			prompt := existing[string(c.name)].Prompt
598			model := existing[string(c.name)].Model
599	
600			fields := BuildReviewPickerFields(
601				string(c.name), curated, discovered, activeHints, prompt,
602				&builtinPicks, &discoveredPicks, &prompt,
603			)
604			fields = append(fields, huh.NewInput().
605				Title("Model (optional)").
606				Description("Leave blank to use the agent default; pass any model string accepted by the agent CLI.").
607				Value(&model))
608	
609			// Prepend a non-blocking header Note so the agent being configured
610			// is always clearly visible.
611			header := huh.NewNote().
612				Title(string(c.ag.Type())).
613				Description(fmt.Sprintf("Agent %d of %d · pick review skills and optional instructions", i+1, len(configurable)))
614			fields = append([]huh.Field{header}, fields...)
615	
616			form := newAccessibleForm(huh.NewGroup(fields...))
617			if err := form.RunWithContext(ctx); err != nil {
618				return nil, fmt.Errorf("picker for %s: %w", c.name, err)
619			}
620	
621			cfg := settings.ReviewConfig{
622				Model:  strings.TrimSpace(model),
623				Skills: dedupeStrings(append(builtinPicks, discoveredPicks...)),
624				Prompt: strings.TrimSpace(prompt),
625			}
626			if !cfg.IsZero() {
627				selected[string(c.name)] = cfg
628			}
629		}
630		// Merge the picker's output with existing entries the picker could not
631		// surface. Without the merge, save would replace s.Review wholesale and
632		// silently drop entries the user had configured for external agents,
633		// uncurated agents, or agents whose hooks are temporarily uninstalled.
634		offered := make(map[string]struct{}, len(configurable))
635		for _, c := range configurable {
636			offered[string(c.name)] = struct{}{}
637		}
638		merged := MergePickerResults(existing, offered, selected)
639	
640		// The emptiness check runs on `merged`, not `selected`.
641		if len(merged) == 0 {
642			return nil, errors.New("no review skills or prompt configured")
643		}
644	
645		masterAgent, err := pickReviewMasterAgentPreference(ctx, merged, existingMaster)
646		if err != nil {
647			return nil, err
648		}
649		if err := saveReviewProfileConfig(ctx, profileName, merged, masterAgent); err != nil {
650			return nil, err
651		}
652		fmt.Fprintf(out, "Saved crew profile %q to local review preferences. Edit later with `entire scout --edit --profile %s`.\n", profileName, profileName)
653		return merged, nil
654	}
655	
656	// MergePickerResults combines the picker's output with existing review
657	// config entries that the picker did not surface. Agents in `offered` are
658	// fully controlled by the picker: if they appear in `selected` with a
659	// non-zero config the entry is set, otherwise the entry is removed.
660	// Agents not in `offered` keep their existing config untouched.
661	//
662	// Exported so tests can drive it directly — the picker itself
663	// can't run headless.
664	func MergePickerResults(existing map[string]settings.ReviewConfig, offered map[string]struct{}, selected map[string]settings.ReviewConfig) map[string]settings.ReviewConfig {
665		merged := make(map[string]settings.ReviewConfig, len(existing)+len(selected))
666		for name, cfg := range existing {
667			if _, wasOffered := offered[name]; !wasOffered {
668				merged[name] = cfg
669			}
670		}
671		for name, cfg := range selected {
672			merged[name] = cfg
673		}
674		return merged
675	}
676	
677	func saveReviewProfileConfig(ctx context.Context, profileName string, agents map[string]settings.ReviewConfig, master string) error {
678		prefs, err := settings.LoadClonePreferences(ctx)
679		if err != nil {
680			return fmt.Errorf("load review preferences before save: %w", err)
681		}
682		if prefs == nil {
683			prefs = &settings.ClonePreferences{}
684		}
685		if prefs.ReviewProfiles == nil {
686			prefs.ReviewProfiles = map[string]settings.ReviewProfileConfig{}
687		}
688		// Merge into any existing profile so the advanced skills picker only
689		// rewrites what it actually edits (agents + master). Profile-level fields
690		// the picker never surfaces — custom `task` text and `master_model` — are
691		// preserved instead of being clobbered with built-in defaults.
692		profile := prefs.ReviewProfiles[profileName]
693		profile.Agents = agents
694		profile.Master = master
695		if strings.TrimSpace(profile.Task) == "" {
696			profile.Task = profileTask(profileName, settings.ReviewProfileConfig{})
697		}
698		prefs.ReviewProfiles[profileName] = profile
699		if prefs.ReviewDefaultProfile == "" {
700			prefs.ReviewDefaultProfile = profileName
701		}
702		if err := settings.SaveClonePreferences(ctx, prefs); err != nil {
703			return fmt.Errorf("save review preferences: %w", err)
704		}
705		return nil
706	}
707	
708	func pickReviewMasterAgentPreference(ctx context.Context, review map[string]settings.ReviewConfig, current string) (string, error) {
709		choices := reviewMasterAgentChoices(review)
710		switch len(choices) {
711		case 0:
712			return current, nil
713		case 1:
714			return choices[0].Name, nil
715		default:
716			return promptForReviewMasterAgent(ctx, choices, current)
717		}
718	}
719	
720	// defaultAgentPick returns the saved choice if it is still offered, otherwise
721	// the first choice. Shared by the master picker.
722	func defaultAgentPick(choices []AgentChoice, saved string) string {
723		if pick, ok := savedAgentPick(choices, saved); ok {
724			return pick
725		}
726		if len(choices) == 0 {
727			return ""
728		}
729		return choices[0].Name
730	}
731	
732	func savedAgentPick(choices []AgentChoice, saved string) (string, bool) {
733		for _, choice := range choices {
734			if choice.Name == saved {
735				return saved, true
736			}
737		}
738		return "", false
739	}
740	
741	func reviewMasterAgentChoices(configured map[string]settings.ReviewConfig) []AgentChoice {
742		choices := make([]AgentChoice, 0, len(configured))
743		for name, cfg := range configured {
744			if cfg.IsZero() {
745				continue
746			}
747			agentName := reviewAgentName(name, cfg)
748			ag, err := agent.Get(types.AgentName(agentName))
749			if err != nil {
750				continue
751			}
752			if _, ok := agent.AsTextGenerator(ag); !ok {
753				continue
754			}
755			label := string(ag.Type())
756			if name != agentName || strings.TrimSpace(cfg.Model) != "" {
757				label = reviewWorkerLabel(name, cfg)
758			}
759			choices = append(choices, AgentChoice{Name: name, Label: label})
760		}
761		sort.Slice(choices, func(i, j int) bool { return choices[i].Name < choices[j].Name })
762		return choices
763	}
764	
765	func promptForReviewMasterAgent(ctx context.Context, choices []AgentChoice, saved string) (string, error) {
766		options := make([]huh.Option[string], 0, len(choices))
767		for _, choice := range choices {
768			options = append(options, huh.NewOption(choice.Label, choice.Name))
769		}
770		picked := defaultAgentPick(choices, saved)
771		form := newAccessibleForm(huh.NewGroup(
772			huh.NewSelect[string]().
773				Title("Choose review master").
774				Description("The master critically evaluates worker reports and writes the final report.").
775				Options(options...).
776				Height(reviewPickerHeight(len(options))).
777				Value(&picked),
778		))
779		if err := form.RunWithContext(ctx); err != nil {
780			return "", fmt.Errorf("review master picker: %w", err)
781		}
782		return picked, nil
783	}
784	
785	// ComputeEligibleConfiguredForProfile returns the sorted list of agents in a
786	// profile that are both configured and have hooks installed.
787	func ComputeEligibleConfiguredForProfile(profile settings.ReviewProfileConfig, installed []types.AgentName) []AgentChoice {
788		return eligibleAgentChoices(profile.Agents, installed)
789	}
790	
791	func eligibleAgentChoices(configured map[string]settings.ReviewConfig, installed []types.AgentName) []AgentChoice {
792		installedSet := make(map[types.AgentName]struct{}, len(installed))
793		for _, name := range installed {
794			installedSet[name] = struct{}{}
795		}
796		out := make([]AgentChoice, 0, len(configured))
797		for name, cfg := range configured {
798			if cfg.IsZero() {
799				continue
800			}
801			if _, ok := installedSet[types.AgentName(reviewAgentName(name, cfg))]; !ok {
802				continue
803			}
804			out = append(out, AgentChoice{Name: name, Label: labelForAgentChoice(name, cfg)})
805		}
806		sort.Slice(out, func(i, j int) bool { return out[i].Name < out[j].Name })
807		return out
808	}
809	
810	// labelForAgentChoice builds the picker-visible label for an agent row.
811	func labelForAgentChoice(name string, cfg settings.ReviewConfig) string {
812		label := reviewWorkerLabel(name, cfg)
813		switch {
814		case len(cfg.Skills) > 0:
815			return fmt.Sprintf("%s   (%d skills configured)", label, len(cfg.Skills))
816		case cfg.Prompt != "":
817			return label + "   (prompt-only)"
818		default:
819			return label
820		}
821	}
822	
823	// computeLaunchableEligibleForProfile returns the subset of
824	// ComputeEligibleConfiguredForProfile that also have a non-nil AgentReviewer.
825	// "Launchable" here is a historical shorthand for "has an Entire review-runner
826	// adapter"; it is not a claim about whether the agent's own CLI supports
827	// headless execution.
828	//
829	// reviewerFor is deps.ReviewerFor injected at the cmd layer; it returns nil for
830	// agents that are known to Entire but not yet wired into `entire review`.
831	func computeLaunchableEligibleForProfile(
832		profile settings.ReviewProfileConfig,
833		installed []types.AgentName,
834		reviewerFor func(string) reviewtypes.AgentReviewer,
835	) []AgentChoice {
836		eligible := ComputeEligibleConfiguredForProfile(profile, installed)
837		return filterLaunchableEligibleForProfile(profile, eligible, reviewerFor)
838	}
839	
840	func filterLaunchableEligibleForProfile(profile settings.ReviewProfileConfig, eligible []AgentChoice, reviewerFor func(string) reviewtypes.AgentReviewer) []AgentChoice {
841		out := make([]AgentChoice, 0, len(eligible))
842		for _, c := range eligible {
843			cfg := profile.Agents[c.Name]
844			if reviewerFor(reviewAgentName(c.Name, cfg)) != nil {
845				out = append(out, c)
846			}
847		}
848		return out
849	}
850	
851	// PromptForAgent renders the single-select agent picker shown when more than
852	// one eligible agent is configured. Returns the chosen agent name. Respects
853	// accessibility mode via newAccessibleForm.
854	func PromptForAgent(ctx context.Context, eligible []AgentChoice) (string, error) {
855		if err := ctx.Err(); err != nil {
856			return "", fmt.Errorf("agent picker: %w", err)
857		}
858		if len(eligible) == 0 {
859			return "", errors.New("no eligible agents to prompt for")
860		}
861		options := make([]huh.Option[string], 0, len(eligible))
862		for _, c := range eligible {
863			options = append(options, huh.NewOption(c.Label, c.Name))
864		}
865		picked := eligible[0].Name
866		form := newAccessibleForm(huh.NewGroup(
867			huh.NewSelect[string]().
868				Title("Which agent should run this review?").
869				Options(options...).
870				Value(&picked),
871		))
872		if err := form.RunWithContext(ctx); err != nil {
873			return "", fmt.Errorf("agent picker: %w", err)
874		}
875		return picked, nil
876	}
877	
878	// SelectReviewAgent picks an agent from the configured review map.
879	//
880	// If override is non-empty, returns the config for that agent or an error
881	// listing the configured alternatives. Otherwise returns the alphabetically
882	// first configured agent — deterministic but user-overridable via --agent.
883	func SelectReviewAgent(review map[string]settings.ReviewConfig, override string) (string, settings.ReviewConfig, error) {
884		if len(review) == 0 {
885			return "", settings.ReviewConfig{}, errors.New("no review config found")
886		}
887		var names []string
888		for name, cfg := range review {
889			if !cfg.IsZero() {
890				names = append(names, name)
891			}
892		}
893		if len(names) == 0 {
894			return "", settings.ReviewConfig{}, errors.New("no review config found")
895		}
896		sort.Strings(names)
897		if override != "" {
898			if cfg, ok := review[override]; ok && !cfg.IsZero() {
899				return override, cfg, nil
900			}
901			return "", settings.ReviewConfig{}, fmt.Errorf(
902				"agent %q is not configured for review; configured agents: %s",
903				override, strings.Join(names, ", "),
904			)
905		}
906		pick := names[0]
907		return pick, review[pick], nil
908	}
909	
910	// VerifyConfiguredSkillsInstalled is the spawn-time backstop for the
911	// silent-failure vector. For each skill in cfg.Skills, check it's either a
912	// curated built-in or returned by the agent's SkillDiscoverer; fail with a
913	// user-facing error if any skill is missing. Empty Skills (prompt-only
914	// config) short-circuits to nil — a freeform prompt has no skill list to
915	// validate against.
916	func VerifyConfiguredSkillsInstalled(ctx context.Context, ag agent.Agent, cfg settings.ReviewConfig) error {
917		if len(cfg.Skills) == 0 {
918			return nil
919		}
920		builtins := builtinNameSet(skilldiscovery.CuratedBuiltinsFor(string(ag.Name())))
921		discoveredNames := map[string]struct{}{}
922		if d, ok := ag.(agent.SkillDiscoverer); ok {
923			if skills, err := d.DiscoverReviewSkills(ctx); err == nil {
924				for _, s := range skills {
925					discoveredNames[s.Name] = struct{}{}
926				}
927			} else {
928				logging.Debug(ctx, "skill verification discovery failed",
929					slog.String("agent", string(ag.Name())), slog.String("error", err.Error()))
930			}
931		}
932		var missing []string
933		for _, s := range cfg.Skills {
934			if _, ok := builtins[s]; ok {
935				continue
936			}
937			if _, ok := discoveredNames[s]; ok {
938				continue
939			}
940			missing = append(missing, s)
941		}
942		if len(missing) == 0 {
943			return nil
944		}
945		return fmt.Errorf(
946			"configured review skill(s) not installed: %s\n"+
947				"run `entire scout --edit` to reconfigure, or install the plugin and retry",
948			strings.Join(missing, ", "),
949		)
950	}
951	
952	// BuildReviewPickerFields composes the per-agent group fields for the
953	// review picker. Returns a slice of huh.Field in render order:
954	//
955	//	0: built-in commands (multiselect) OR note
956	//	1: installed plugin skills (multiselect) OR note
957	//	2: install hints (note with all active hint messages) — OMITTED if empty
958	//	3: additional instructions (text) — always present
959	func BuildReviewPickerFields(
960		agentName string,
961		builtins []skilldiscovery.CuratedSkill,
962		discovered []agent.DiscoveredSkill,
963		activeHints []skilldiscovery.InstallHint,
964		previousPrompt string,
965		builtinPicksOut, discoveredPicksOut *[]string,
966		promptOut *string,
967	) []huh.Field {
968		var fields []huh.Field
969	
970		if builtinPicksOut != nil && len(*builtinPicksOut) == 0 &&
971			len(builtins) == 1 && strings.TrimSpace(previousPrompt) == "" {
972			*builtinPicksOut = []string{builtins[0].Name}
973		}
974	
975		builtinPreselected := preselectedSet(builtinPicksOut)
976		discoveredPreselected := preselectedSet(discoveredPicksOut)
977	
978		if len(builtins) > 0 {
979			opts := make([]huh.Option[string], 0, len(builtins))
980			for _, b := range builtins {
981				opt := huh.NewOption(b.Name, b.Name)
982				if _, ok := builtinPreselected[b.Name]; ok {
983					opt = opt.Selected(true)
984				}
985				opts = append(opts, opt)
986			}
987			ms := huh.NewMultiSelect[string]().
988				Title("Built-in commands").
989				Options(opts...).
990				Height(len(opts) + 1)
991			if builtinPicksOut != nil {
992				ms = ms.Value(builtinPicksOut)
993			}
994			fields = append(fields, ms)
995		} else {
996			fields = append(fields, huh.NewNote().
997				Title("Built-in commands").
998				Description(fmt.Sprintf("No built-in review commands in %s.", agentName)))
999		}
1000	
1001		if len(discovered) > 0 {
1002			opts := make([]huh.Option[string], 0, len(discovered))
1003			for _, d := range discovered {
1004				opt := huh.NewOption(d.Name, d.Name)
1005				if _, ok := discoveredPreselected[d.Name]; ok {
1006					opt = opt.Selected(true)
1007				}
1008				opts = append(opts, opt)
1009			}
1010			ms := huh.NewMultiSelect[string]().
1011				Title("Installed plugin skills").
1012				Options(opts...).
1013				Height(len(opts) + 1)
1014			if discoveredPicksOut != nil {
1015				ms = ms.Value(discoveredPicksOut)
1016			}
1017			fields = append(fields, ms)
1018		} else {
1019			fields = append(fields, huh.NewNote().
1020				Title("Installed plugin skills").
1021				Description("No plugin review skills detected on disk."))
1022		}
1023	
1024		if len(activeHints) > 0 {
1025			var sb strings.Builder
1026			for i, h := range activeHints {
1027				if i > 0 {
1028					sb.WriteString("\n")
1029				}
1030				sb.WriteString("• ")
1031				sb.WriteString(h.Message)
1032			}
1033			fields = append(fields, huh.NewNote().
1034				Title("Install more").
1035				Description(sb.String()))
1036		}
1037	
1038		text := huh.NewText().
1039			Title("Additional instructions (optional)").
1040			Description("Added after selected skills. If no skills are selected, this becomes the full review prompt.")
1041		if promptOut != nil {
1042			*promptOut = previousPrompt
1043			text = text.Value(promptOut)
1044		}
1045		fields = append(fields, text)
1046	
1047		return fields
1048	}
1049	
1050	// SplitSavedPicks partitions a flat saved-skills list into the subset that
1051	// matches built-in curated commands and the subset that matches discovered
1052	// plugin skills. Skill names that match neither are dropped from both — they're
1053	// preserved on the settings side via MergePickerResults when they belong to a
1054	// picker-unaware agent entry.
1055	func SplitSavedPicks(saved []string, builtins []skilldiscovery.CuratedSkill, discovered []agent.DiscoveredSkill) ([]string, []string) {
1056		builtinNames := make(map[string]struct{}, len(builtins))
1057		for _, b := range builtins {
1058			builtinNames[b.Name] = struct{}{}
1059		}
1060		discoveredNames := make(map[string]struct{}, len(discovered))
1061		for _, d := range discovered {
1062			discoveredNames[d.Name] = struct{}{}
1063		}
1064		var builtinPicks, discoveredPicks []string
1065		for _, s := range saved {
1066			if _, ok := builtinNames[s]; ok {
1067				builtinPicks = append(builtinPicks, s)
1068				continue
1069			}
1070			if _, ok := discoveredNames[s]; ok {
1071				discoveredPicks = append(discoveredPicks, s)
1072			}
1073		}
1074		return builtinPicks, discoveredPicks
1075	}
1076	
1077	// preselectedSet turns a slice pointer's current contents into a lookup
1078	// set for the picker's "previously-saved" pre-selection.
1079	func preselectedSet(slice *[]string) map[string]struct{} {
1080		if slice == nil || len(*slice) == 0 {
1081			return nil
1082		}
1083		out := make(map[string]struct{}, len(*slice))
1084		for _, s := range *slice {
1085			out[s] = struct{}{}
1086		}
1087		return out
1088	}
1089	
1090	func builtinNameSet(curated []skilldiscovery.CuratedSkill) map[string]struct{} {
1091		set := make(map[string]struct{}, len(curated))
1092		for _, c := range curated {
1093			set[c.Name] = struct{}{}
1094		}
1095		return set
1096	}
1097	
1098	// filterOutBuiltinCollisions drops any discovered skill whose name collides
1099	// with a curated built-in. Built-in wins because it carries a richer,
1100	// hand-authored description.
1101	func filterOutBuiltinCollisions(discovered []agent.DiscoveredSkill, builtins map[string]struct{}) []agent.DiscoveredSkill {
1102		if len(discovered) == 0 || len(builtins) == 0 {
1103			return discovered
1104		}
1105		out := make([]agent.DiscoveredSkill, 0, len(discovered))
1106		for _, d := range discovered {
1107			if _, clash := builtins[d.Name]; clash {
1108				continue
1109			}
1110			out = append(out, d)
1111		}
1112		return out
1113	}
1114	
1115	func dedupeStrings(xs []string) []string {
1116		if len(xs) == 0 {
1117			return xs
1118		}
1119		seen := make(map[string]struct{}, len(xs))
1120		out := make([]string, 0, len(xs))
1121		for _, x := range xs {
1122			if _, ok := seen[x]; ok {
1123				continue
1124			}
1125			seen[x] = struct{}{}
1126			out = append(out, x)
1127		}
1128		return out
1129	}
