1	package pi
2	
3	import (
4		"bufio"
5		"context"
6		"encoding/json"
7		"fmt"
8		"io"
9		"os"
10		"os/exec"
11	
12		"github.com/entireio/cli/cmd/entire/cli/review"
13		reviewtypes "github.com/entireio/cli/cmd/entire/cli/review/types"
14	)
15	
16	// piReviewMaxScannerBuf is the bufio.Scanner cap for the Pi review parser.
17	// 64MB matches the claude-code and codex parsers so all three tolerate the
18	// same worst-case line length (a tool result packed into one JSON envelope).
19	const piReviewMaxScannerBuf = 64 * 1024 * 1024
20	
21	// NewReviewer returns the AgentReviewer for the Pi coding agent.
22	//
23	// Argv shape: pi --mode json <prompt> [--model <pattern>]. The prompt is a
24	// positional argument; stdin is unused. Stdout is newline-delimited JSON
25	// event envelopes (one event per line, see Pi's docs/json.md), which the
26	// parser decodes into the review Event stream.
27	//
28	// Pi spawned this way is a child process of `entire review`, so it inherits
29	// the ENTIRE_REVIEW_* env vars set by AppendReviewEnv. Pi's lifecycle hook
30	// then self-tags the session as a review via the shared adoptReviewEnv path —
31	// no marker file and no `entire attach` are needed.
32	func NewReviewer() *reviewtypes.ReviewerTemplate {
33		return &reviewtypes.ReviewerTemplate{
34			AgentName: "pi",
35			BuildCmd:  buildReviewCmd,
36			Parser:    parsePiOutput,
37		}
38	}
39	
40	// buildReviewCmd builds the exec.Cmd for a Pi review run.
41	// Exposed at package level for test inspection of argv and env.
42	func buildReviewCmd(ctx context.Context, cfg reviewtypes.RunConfig) *exec.Cmd {
43		prompt := review.ComposeReviewPrompt(cfg)
44		args := []string{"--mode", "json", prompt}
45		if cfg.Model != "" {
46			args = append(args, "--model", cfg.Model)
47		}
48		cmd := exec.CommandContext(ctx, "pi", args...)
49		cmd.Env = review.AppendReviewEnv(os.Environ(), "pi", cfg, prompt)
50		return cmd
51	}
52	
53	// piStreamEnvelope is one line of `pi --mode json` stdout. Only the fields the
54	// review parser consumes are declared; unknown fields and event types are
55	// ignored so new Pi event types don't break parsing.
56	type piStreamEnvelope struct {
57		Type     string           `json:"type"`
58		ToolName string           `json:"toolName"`
59		Args     json.RawMessage  `json:"args"`
60		Message  *piStreamMessage `json:"message"`
61	}
62	
63	type piStreamMessage struct {
64		Role    string          `json:"role"`
65		Content json.RawMessage `json:"content"`
66		Usage   *piStreamUsage  `json:"usage"`
67	}
68	
69	// piStreamUsage mirrors pi-ai's Usage shape (token counts only).
70	type piStreamUsage struct {
71		Input      int `json:"input"`
72		Output     int `json:"output"`
73		CacheRead  int `json:"cacheRead"`
74		CacheWrite int `json:"cacheWrite"`
75	}
76	
77	type piStreamContentBlock struct {
78		Type string `json:"type"`
79		Text string `json:"text"`
80	}
81	
82	// parsePiOutput converts `pi --mode json` stdout into a stream of review
83	// Events. Each stdout line is one JSON envelope:
84	//   - {"type":"session",...}            session header; swallowed
85	//   - {"type":"agent_start"}            covered by the leading Started event
86	//   - {"type":"message_end","message":{role:"assistant",content:[...],usage}}
87	//     assistant text → AssistantText; usage tallied for the final Tokens event
88	//   - {"type":"tool_execution_start","toolName":..,"args":..} → ToolCall
89	//   - {"type":"agent_end",...}          marks a clean completion
90	//
91	// Emits Started first, Finished{Success:...} last. Success is true only when
92	// an agent_end envelope was observed. On a scanner error (torn stream) it
93	// emits RunError then Finished{Success:false}.
94	//
95	// Token math: Pi reports per-message usage on each assistant message. Output
96	// tokens are summed across messages; input is taken from the last assistant
97	// message (its context already includes prior turns, so summing input would
98	// double-count). These are advisory live totals — the authoritative figures
99	// are hydrated from the persisted transcript after the run.
100	func parsePiOutput(r io.Reader) <-chan reviewtypes.Event {
101		return parsePiOutputBuf(r, piReviewMaxScannerBuf)
102	}
103	
104	// parsePiOutputBuf is the parameterized variant of parsePiOutput, used by
105	// tests to shrink the scanner cap so the "token too long" branch can be
106	// exercised without writing 64MB of fixture data.
107	func parsePiOutputBuf(r io.Reader, maxBuf int) <-chan reviewtypes.Event {
108		out := make(chan reviewtypes.Event, 32)
109		go func() {
110			defer close(out)
111			out <- reviewtypes.Started{}
112			scanner := bufio.NewScanner(r)
113			scanner.Buffer(make([]byte, min(1024*1024, maxBuf)), maxBuf)
114			var sawEnd bool
115			var sumOut, lastIn int
116			for scanner.Scan() {
117				line := scanner.Bytes()
118				if len(line) == 0 {
119					continue
120				}
121				var env piStreamEnvelope
122				if err := json.Unmarshal(line, &env); err != nil {
123					out <- reviewtypes.RunError{Err: fmt.Errorf("pi json stream: %w", err)}
124					continue
125				}
126				switch env.Type {
127				case "message_end":
128					if env.Message == nil || env.Message.Role != "assistant" {
129						continue
130					}
131					for _, text := range assistantTextBlocks(env.Message.Content) {
132						if text != "" {
133							out <- reviewtypes.AssistantText{Text: text}
134						}
135					}
136					if u := env.Message.Usage; u != nil {
137						sumOut += u.Output
138						lastIn = u.Input + u.CacheRead
139					}
140				case "tool_execution_start":
141					out <- reviewtypes.ToolCall{Name: env.ToolName, Args: string(env.Args)}
142				case "agent_end":
143					sawEnd = true
144				}
145			}
146			if err := scanner.Err(); err != nil {
147				out <- reviewtypes.RunError{Err: fmt.Errorf("read stdout: %w", err)}
148				out <- reviewtypes.Finished{Success: false}
149				return
150			}
151			out <- reviewtypes.Tokens{In: lastIn, Out: sumOut}
152			out <- reviewtypes.Finished{Success: sawEnd}
153		}()
154		return out
155	}
156	
157	// assistantTextBlocks extracts the text from a Pi assistant message's content,
158	// which is normally an array of content blocks but may be a plain JSON string.
159	// Non-text blocks (tool calls, etc.) are ignored — tool activity is surfaced
160	// via the dedicated tool_execution_start envelope instead.
161	func assistantTextBlocks(content json.RawMessage) []string {
162		if len(content) == 0 {
163			return nil
164		}
165		var blocks []piStreamContentBlock
166		if err := json.Unmarshal(content, &blocks); err == nil {
167			var texts []string
168			for _, b := range blocks {
169				if b.Type == "text" && b.Text != "" {
170					texts = append(texts, b.Text)
171				}
172			}
173			return texts
174		}
175		var s string
176		if err := json.Unmarshal(content, &s); err == nil && s != "" {
177			return []string{s}
178		}
179		return nil
180	}
