package pi

import (
	"bufio"
	"context"
	"encoding/json"
	"fmt"
	"io"
	"os"
	"os/exec"

	"github.com/entireio/cli/cmd/entire/cli/review"
	reviewtypes "github.com/entireio/cli/cmd/entire/cli/review/types"
)

// piReviewMaxScannerBuf is the bufio.Scanner cap for the Pi review parser.
// 64MB matches the claude-code and codex parsers so all three tolerate the
// same worst-case line length (a tool result packed into one JSON envelope).
const piReviewMaxScannerBuf = 64 * 1024 * 1024

// NewReviewer returns the AgentReviewer for the Pi coding agent.
//
// Argv shape: pi --mode json <prompt> [--model <pattern>]. The prompt is a
// positional argument; stdin is unused. Stdout is newline-delimited JSON
// event envelopes (one event per line, see Pi's docs/json.md), which the
// parser decodes into the review Event stream.
//
// Pi spawned this way is a child process of `entire review`, so it inherits
// the ENTIRE_REVIEW_* env vars set by AppendReviewEnv. Pi's lifecycle hook
// then self-tags the session as a review via the shared adoptReviewEnv path —
// no marker file and no `entire attach` are needed.
func NewReviewer() *reviewtypes.ReviewerTemplate {
	return &reviewtypes.ReviewerTemplate{
		AgentName: "pi",
		BuildCmd:  buildReviewCmd,
		Parser:    parsePiOutput,
	}
}

// buildReviewCmd builds the exec.Cmd for a Pi review run.
// Exposed at package level for test inspection of argv and env.
func buildReviewCmd(ctx context.Context, cfg reviewtypes.RunConfig) *exec.Cmd {
	prompt := review.ComposeReviewPrompt(cfg)
	args := []string{"--mode", "json", prompt}
	if cfg.Model != "" {
		args = append(args, "--model", cfg.Model)
	}
	cmd := exec.CommandContext(ctx, "pi", args...)
	cmd.Env = review.AppendReviewEnv(os.Environ(), "pi", cfg, prompt)
	return cmd
}

// piStreamEnvelope is one line of `pi --mode json` stdout. Only the fields the
// review parser consumes are declared; unknown fields and event types are
// ignored so new Pi event types don't break parsing.
type piStreamEnvelope struct {
	Type     string           `json:"type"`
	ToolName string           `json:"toolName"`
	Args     json.RawMessage  `json:"args"`
	Message  *piStreamMessage `json:"message"`
}

type piStreamMessage struct {
	Role    string          `json:"role"`
	Content json.RawMessage `json:"content"`
	Usage   *piStreamUsage  `json:"usage"`
}

// piStreamUsage mirrors pi-ai's Usage shape (token counts only).
type piStreamUsage struct {
	Input      int `json:"input"`
	Output     int `json:"output"`
	CacheRead  int `json:"cacheRead"`
	CacheWrite int `json:"cacheWrite"`
}

type piStreamContentBlock struct {
	Type string `json:"type"`
	Text string `json:"text"`
}

// parsePiOutput converts `pi --mode json` stdout into a stream of review
// Events. Each stdout line is one JSON envelope:
//   - {"type":"session",...}            session header; swallowed
//   - {"type":"agent_start"}            covered by the leading Started event
//   - {"type":"message_end","message":{role:"assistant",content:[...],usage}}
//     assistant text → AssistantText; usage tallied for the final Tokens event
//   - {"type":"tool_execution_start","toolName":..,"args":..} → ToolCall
//   - {"type":"agent_end",...}          marks a clean completion
//
// Emits Started first, Finished{Success:...} last. Success is true only when
// an agent_end envelope was observed. On a scanner error (torn stream) it
// emits RunError then Finished{Success:false}.
//
// Token math: Pi reports per-message usage on each assistant message. Output
// tokens are summed across messages; input is taken from the last assistant
// message (its context already includes prior turns, so summing input would
// double-count). These are advisory live totals — the authoritative figures
// are hydrated from the persisted transcript after the run.
func parsePiOutput(r io.Reader) <-chan reviewtypes.Event {
	return parsePiOutputBuf(r, piReviewMaxScannerBuf)
}

// parsePiOutputBuf is the parameterized variant of parsePiOutput, used by
// tests to shrink the scanner cap so the "token too long" branch can be
// exercised without writing 64MB of fixture data.
func parsePiOutputBuf(r io.Reader, maxBuf int) <-chan reviewtypes.Event {
	out := make(chan reviewtypes.Event, 32)
	go func() {
		defer close(out)
		out <- reviewtypes.Started{}
		scanner := bufio.NewScanner(r)
		scanner.Buffer(make([]byte, min(1024*1024, maxBuf)), maxBuf)
		var sawEnd bool
		var sumOut, lastIn int
		for scanner.Scan() {
			line := scanner.Bytes()
			if len(line) == 0 {
				continue
			}
			var env piStreamEnvelope
			if err := json.Unmarshal(line, &env); err != nil {
				out <- reviewtypes.RunError{Err: fmt.Errorf("pi json stream: %w", err)}
				continue
			}
			switch env.Type {
			case "message_end":
				if env.Message == nil || env.Message.Role != "assistant" {
					continue
				}
				for _, text := range assistantTextBlocks(env.Message.Content) {
					if text != "" {
						out <- reviewtypes.AssistantText{Text: text}
					}
				}
				if u := env.Message.Usage; u != nil {
					sumOut += u.Output
					lastIn = u.Input + u.CacheRead
				}
			case "tool_execution_start":
				out <- reviewtypes.ToolCall{Name: env.ToolName, Args: string(env.Args)}
			case "agent_end":
				sawEnd = true
			}
		}
		if err := scanner.Err(); err != nil {
			out <- reviewtypes.RunError{Err: fmt.Errorf("read stdout: %w", err)}
			out <- reviewtypes.Finished{Success: false}
			return
		}
		out <- reviewtypes.Tokens{In: lastIn, Out: sumOut}
		out <- reviewtypes.Finished{Success: sawEnd}
	}()
	return out
}

// assistantTextBlocks extracts the text from a Pi assistant message's content,
// which is normally an array of content blocks but may be a plain JSON string.
// Non-text blocks (tool calls, etc.) are ignored — tool activity is surfaced
// via the dedicated tool_execution_start envelope instead.
func assistantTextBlocks(content json.RawMessage) []string {
	if len(content) == 0 {
		return nil
	}
	var blocks []piStreamContentBlock
	if err := json.Unmarshal(content, &blocks); err == nil {
		var texts []string
		for _, b := range blocks {
			if b.Type == "text" && b.Text != "" {
				texts = append(texts, b.Text)
			}
		}
		return texts
	}
	var s string
	if err := json.Unmarshal(content, &s); err == nil && s != "" {
		return []string{s}
	}
	return nil
}

func NewCommand(deps Deps) *cobra.Command {
	var configure bool
	var edit bool
	var agentOverride string
	var modelOverride string
	var baseOverride string
	var profileOverride string
	var perRunPrompt string
	var findings bool
	var listModels bool
	var listAgents bool
	var setAgents []string
	var setMaster string
	var setTask string
	var setModels []string
	var setSlots []string

	cmd := &cobra.Command{
		Use: "scout",
		// `review` is kept as an alias for back-compat while scout matures.
		Aliases: []string{"review"},
		// Hidden from `entire help` while the feature is still maturing —
		// users who know about it can still run `entire scout` / `entire
		// scout --help` and the command works normally.
		Hidden: true,
		Short:  "Run a multi-agent crew against the current branch",
		Long: `Run a multi-agent crew against the current branch: several worker
agents inspect the change in parallel, then a master agent synthesizes their
reports into a final verdict. Crews are saved as named profiles in Entire
settings and clone-local preferences. On first run, guided setup writes a
profile and asks before starting agents.

Labs entry: scout is experimental. We are actively refining it based on user
feedback.

The session is recorded as part of the next checkpoint, so the metadata is
permanently attached to the commit it covers.

Flags:
  --configure    set up a crew profile (shows available agents + profiles).
                 With --set-* flags it writes the profile non-interactively;
                 otherwise it opens the wizard (interactive) without starting agents.
  --set-agents   with --configure: comma-separated worker agents for the profile
  --set-master   with --configure: master agent that writes the final report
  --set-task     with --configure: the profile's canonical task text
  --set-model    with --configure: per-worker model as agent=model (repeatable)
  --set-slot     with --configure: a worker slot as agent[=model] (repeatable;
                 the same agent/model may repeat to run it multiple times)
  --edit         re-open the advanced profile skill picker
  --findings     browse local findings
  --agent NAME   run only one worker from the selected profile
  --agents       list the worker agents you can pass to --agent for the profile
  --model NAME   override the model for the --agent worker (requires --agent)
  --models       list the models each agent advertises (optionally --agent NAME)
  --profile NAME select a profile (also accepted as positional arg)
  --prompt TEXT  add one-off per-run instructions for this invocation
  --base REF     scope against REF instead of mainline. Useful for stacked
                 PRs where the base is the parent feature branch, not main.
                 Default: first existing of origin/HEAD, origin/main,
                 origin/master, main, master.

Aliased as 'entire review'. To tag an already-finished session as a review,
use 'entire attach --review <id>'.`,
		Args: func(_ *cobra.Command, args []string) error {
			if len(args) > 1 {
				return fmt.Errorf("accepts at most one argument, received %d", len(args))
			}
			if len(args) == 1 && profileOverride != "" {
				return errors.New("pass profile either positionally or with --profile, not both")
			}
			return nil
		},
		RunE: func(cmd *cobra.Command, args []string) error {
			ctx := cmd.Context()
			// Discover external agents so review configs that target them
			// resolve correctly — without this, GetAgentsWithHooksInstalled
			// and agent.Get can't see them.
			external.DiscoverAndRegister(ctx)

			if listModels {
				return runReviewListModels(ctx, cmd, agentOverride, deps)
			}
			if listAgents {
				listProfile := profileOverride
				if len(args) == 1 {
					listProfile = args[0]
				}
				return runReviewListAgents(ctx, cmd, listProfile, deps)
			}

			modes := 0
			for _, enabled := range []bool{configure, edit, findings} {
				if enabled {
					modes++
				}
			}
			if modes > 1 {
				return errors.New("--configure, --edit, and --findings are mutually exclusive")
			}
			if modelOverride != "" && agentOverride == "" {
				return errors.New("--model requires --agent (the model applies to a single worker)")
			}
			profileName := profileOverride
			if len(args) == 1 {
				profileName = args[0]
			}
			if configure {
				return runReviewConfigure(ctx, cmd, profileName, reviewConfigureOptions{
					Agents: setAgents,
					Master: setMaster,
					Task:   setTask,
					Models: setModels,
					Slots:  setSlots,
				}, deps)
			}
			if edit {
				_, err := RunReviewProfileConfigPicker(ctx, cmd.OutOrStdout(), deps.GetAgentsWithHooksInstalled, profileName)
				return err
			}
			if findings {
				return runReviewFindings(ctx, cmd, deps.NewSilentError)
			}
			return runReview(ctx, cmd, agentOverride, modelOverride, baseOverride, profileName, perRunPrompt, deps)
		},
	}
	cmd.Flags().BoolVar(&configure, "configure", false, "set up a review profile; shows available agents and accepts --set-* flags for non-interactive config")
	cmd.Flags().StringSliceVar(&setAgents, "set-agents", nil, "with --configure: worker agents for the profile (comma-separated)")
	cmd.Flags().StringVar(&setMaster, "set-master", "", "with --configure: master agent that writes the final report")
	cmd.Flags().StringVar(&setTask, "set-task", "", "with --configure: the profile's canonical task text")
	cmd.Flags().StringArrayVar(&setModels, "set-model", nil, "with --configure: per-worker model as agent=model (repeatable)")
	cmd.Flags().StringArrayVar(&setSlots, "set-slot", nil, "with --configure: a worker slot as agent[=model] (repeatable; same agent/model may repeat)")
	cmd.Flags().BoolVar(&edit, "edit", false, "re-open the advanced review profile skill picker")
	cmd.Flags().BoolVar(&findings, "findings", false, "browse local review findings")
	cmd.Flags().BoolVar(&listAgents, "agents", false, "list the worker agents you can pass to --agent for the selected profile")
	cmd.Flags().BoolVar(&listModels, "models", false, "list the models each review agent advertises (optionally filtered by --agent)")
	cmd.Flags().StringVar(&agentOverride, "agent", "", "run one configured worker from the selected profile")
	cmd.Flags().StringVar(&modelOverride, "model", "", "override the model for the --agent worker (requires --agent)")
	cmd.Flags().StringVar(&profileOverride, "profile", "", "review profile to run (default: review_default_profile or general)")
	cmd.Flags().StringVar(&perRunPrompt, "prompt", "", "one-off instructions appended to this review run")
	cmd.Flags().StringVar(&baseOverride, "base", "", "git ref to scope the review against (default: origin/HEAD → origin/main → origin/master → main → master)")
	return cmd
}

// reviewConfigureOptions carries the non-interactive `--configure` inputs.
type reviewConfigureOptions struct {
	Agents []string // worker agent names (--set-agents)
	Master string   // master agent (--set-master)
	Task   string   // profile task text (--set-task)
	Models []string // per-worker "agent=model" entries (--set-model)
	Slots  []string // worker slots as "agent[=model]" entries (--set-slot)
}

