221	func (o reviewConfigureOptions) scripted() bool {
222		return len(o.Agents) > 0 || o.Master != "" || o.Task != "" || len(o.Models) > 0 || len(o.Slots) > 0
223	}
224	
225	func runReviewConfigure(ctx context.Context, cmd *cobra.Command, profileOverride string, opts reviewConfigureOptions, deps Deps) error {
226		out := cmd.OutOrStdout()
227		silentErr := deps.NewSilentError
228		if _, err := paths.WorktreeRoot(ctx); err != nil {
229			cmd.SilenceUsage = true
230			fmt.Fprintln(cmd.ErrOrStderr(), "Not a git repository. Run `entire enable` first.")
231			return silentErr(errors.New("not a git repository"))
232		}
233		s, err := settings.Load(ctx)
234		if err != nil {
235			cmd.SilenceUsage = true
236			fmt.Fprintf(cmd.ErrOrStderr(), "Failed to load settings: %v\n", err)
237			return silentErr(err)
238		}
239		if s == nil {
240			s = &settings.EntireSettings{}
241		}
242		profileName := strings.TrimSpace(profileOverride)
243		if profileName == "" {
244			profileName = strings.TrimSpace(s.ReviewDefaultProfile)
245		}
246		if profileName == "" {
247			profileName = DefaultProfileName
248		}
249		installed := deps.GetAgentsWithHooksInstalled(ctx)
250	
251		// Scripted path: build + save the profile from --set-* flags, no TUI.
252		if opts.scripted() {
253			profile, buildErr := buildConfiguredProfile(ctx, profileName, opts, s, deps)
254			if buildErr != nil {
255				cmd.SilenceUsage = true
256				fmt.Fprintln(cmd.ErrOrStderr(), buildErr.Error())
257				return silentErr(buildErr)
258			}
259			if err := saveReviewProfile(ctx, profileName, profile, true); err != nil {
260				return err
261			}
262			fmt.Fprintf(out, "Review profile %q saved with %s.\n", profileName, strings.Join(sortedProfileAgentNames(profile), ", "))
263			fmt.Fprintf(out, "Run `entire scout %s` to start.\n", profileName)
264			return nil
265		}
266	
267		// Interactive path: the guided wizard already lists the agents, so don't
268		// duplicate the catalog here.
269		if interactive.IsTerminalWriter(out) && interactive.CanPromptInteractively() {
270			name, profile, setupErr := RunReviewGuidedSetup(ctx, out, installed, deps.ReviewerFor, profileName, false)
271			if setupErr != nil {
272				return handlePickerError(cmd, silentErr, setupErr)
273			}
274			if err := saveReviewProfile(ctx, name, profile, true); err != nil {
275				return err
276			}
277			fmt.Fprintf(out, "Crew profile %q saved. Run `entire scout`, or `entire scout %s`, to start.\n", name, name)
278			return nil
279		}
280	
281		// Non-interactive with no --set-* flags: this is the discovery view — show
282		// the available agents, current profiles, and how to configure.
283		catalog := availableReviewAgents(installed, deps.ReviewerFor)
284		printReviewConfigCatalog(out, profileName, catalog, s)
285		return nil
286	}
287	
288	// runReviewListModels prints the models each review-runner agent advertises
289	// (claude-code, codex, gemini, ...). It needs no git repo or profile: model
290	// lists are advisory metadata. With agentFilter set, only that agent is shown.
291	func runReviewListModels(ctx context.Context, cmd *cobra.Command, agentFilter string, deps Deps) error {
292		out := cmd.OutOrStdout()
293		installed := deps.GetAgentsWithHooksInstalled(ctx)
294		catalog := availableReviewAgents(installed, deps.ReviewerFor)
295	
296		if agentFilter != "" {
297			filtered := make([]reviewAgentCatalogEntry, 0, 1)
298			for _, e := range catalog {
299				if e.Name == agentFilter {
300					filtered = append(filtered, e)
301				}
302			}
303			if len(filtered) == 0 {
304				cmd.SilenceUsage = true
305				err := fmt.Errorf("agent %q has no review runner adapter; available: %s", agentFilter, strings.Join(reviewAgentNames(deps), ", "))
306				fmt.Fprintln(cmd.ErrOrStderr(), err.Error())
307				return deps.NewSilentError(err)
308			}
309			catalog = filtered
310		}
311	
312		for _, e := range catalog {
313			fmt.Fprintf(out, "%s:\n", e.Name)
314			ag, getErr := agent.Get(types.AgentName(e.Name))
315			if getErr != nil {
316				fmt.Fprintln(out, "  (agent unavailable)")
317				continue
318			}
319			lister, ok := agent.AsModelLister(ag)
320			if !ok {
321				fmt.Fprintln(out, "  (no advertised models; pass any value your CLI accepts via --model)")
322				continue
323			}
324			models, listErr := lister.ListModels(ctx)
325			if listErr != nil || len(models) == 0 {
326				fmt.Fprintln(out, "  (model list unavailable)")
327				continue
328			}
329			for _, m := range models {
330				if m.Note != "" {
331					fmt.Fprintf(out, "  %-18s %s\n", m.ID, m.Note)
332				} else {
333					fmt.Fprintf(out, "  %s\n", m.ID)
334				}
335			}
336		}
337	
338		fmt.Fprintln(out)
339		fmt.Fprintln(out, "These are common models/aliases, not an exhaustive list. Use one with:")
340		fmt.Fprintln(out, "  entire scout --agent <name> --model <model>")
341		return nil
342	}
343	
344	const reviewHooksInstalledStatus = "hooks installed"
345	
346	// runReviewListAgents lists the worker agents valid for `--agent` in the
347	// resolved profile (with hook-install status and the master marked). With no
348	// usable profile it falls back to the available review-agent catalog.
349	func runReviewListAgents(ctx context.Context, cmd *cobra.Command, profileOverride string, deps Deps) error {
350		out := cmd.OutOrStdout()
351		installed := deps.GetAgentsWithHooksInstalled(ctx)
352		installedSet := make(map[string]struct{}, len(installed))
353		for _, n := range installed {
354			installedSet[string(n)] = struct{}{}
355		}
356	
357		s, err := settings.Load(ctx)
358		if err == nil && s != nil {
359			if name, profile, selErr := selectReviewProfile(s, profileOverride); selErr == nil {
360				profile.Agents = nonZeroAgentConfigs(profile.Agents)
361				fmt.Fprintf(out, "Workers in review profile %q (pass one to --agent):\n", name)
362				for _, worker := range sortedProfileAgentNames(profile) {
363					cfg := profile.Agents[worker]
364					status := reviewHooksInstalledStatus
365					if _, ok := installedSet[reviewAgentName(worker, cfg)]; !ok {
366						status = "hooks NOT installed — run `entire configure --agent " + reviewAgentName(worker, cfg) + "`"
367					}
368					marker := ""
369					if worker == profile.Master {
370						marker = "  [master]"
371					}
372					fmt.Fprintf(out, "  %s — %s%s\n", reviewWorkerLabel(worker, cfg), status, marker)
